        await(()->!((ScaleActivity)activity).worker.isAlive(),"Catalog ready");runOnMainSync(()->((ScaleActivity)activity).query.setText("groundwater"));click("Search reference");
        await(()->!((ScaleActivity)activity).worker.isAlive(),"Source search complete");ok(((ScaleActivity)activity).results.getChildCount()>0,"Real groundwater passages found");screenshot("library-results");
