        runOnMainSync(()->((ScaleActivity)activity).results.getChildAt(0).performClick());Activity reader=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);ok(reader instanceof SourceReaderActivity,"Real source opens full-screen reader");Activity libraryActivity=activity;runOnMainSync(libraryActivity::finish);activity=reader;
        await(()->((SourceReaderActivity)activity).content!=null,"Reader content");SourceReaderActivity r=(SourceReaderActivity)activity;savedId=r.recordId;ok(r.entry.body.contains("Source date / retrieval:"),"Actual source date retained");ok(r.entry.body.contains("Citation: [water-"),"Source identity retained");ok(r.entry.body.contains("USGS"),"Actual source rights retained");if(r.cream){click("Reading options");click("Switch reading theme");click("Reading options");}runOnMainSync(()->((SourceReaderActivity)activity).scroll.scrollTo(0,0));screenshot("source-dark");
        String longTitle=r.entry.title+" — source title layout control".repeat(14);runOnMainSync(()->ReaderUi.reader(activity,longTitle,r.entry.body));screenshot("long-title-dialog");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);waitForIdleSync();
        click("Bookmark this record");await(()->r.entry.bookmark,"Bookmark persisted");
        runOnMainSync(()->{r.note.setText("UI verification note: retain the source date and citation identity when exporting this offline source.");view("Save note").performClick();});await(()->r.entry.note.startsWith("UI verification note"),"Note saved");
        click("Reading options");runOnMainSync(()->((Spinner)view("Reader font size")).setSelection(2));click("Switch reading theme");click("Reading options");runOnMainSync(()->dimensions(activity.getWindow().getDecorView()));runOnMainSync(()->((SourceReaderActivity)activity).scroll.scrollTo(0,0));screenshot("source-paper-large");
        try(NotebookStore store=new NotebookStore(getTargetContext())){NotebookStore.Entry e=store.get(savedId);ok(e.bookmark&&e.note.startsWith("UI verification note"),"Notebook survives new database connection");ok(store.list("groundwater",true).stream().anyMatch(x->x.id==savedId),"Bookmark search uses real saved source");}
